SET LOCAL lock_timeout = '5s';--> statement-breakpoint

-- Decides whether Stalwart may deliver a Sieve-generated automatic forward
-- (Outlook rules, JMAP mail rules, Sieve redirect/notify) from `p_sender` to
-- `p_rcpt` (#526). Called once per autogenerated recipient from
-- MtaOutboundStrategy.route ahead of `is_local_domain(rcpt_domain)`.
--
-- ⚠ FAIL CLOSED. Unknown senders, tenantless accounts, malformed inputs and
-- unowned or displaced domains all return false.
CREATE FUNCTION "core"."auto_forward_allowed"(p_sender text, p_rcpt text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  v_sender text;
  v_rcpt text;
  v_rcpt_domain text;
  v_tenant_id uuid;
  v_mode identity.auto_forwarding_mode;
BEGIN
  IF p_sender IS NULL OR p_rcpt IS NULL THEN
    RETURN false;
  END IF;

  v_sender := lower(btrim(p_sender));
  v_rcpt := lower(btrim(p_rcpt));

  IF v_sender = '' OR v_rcpt = '' THEN
    RETURN false;
  END IF;

  v_rcpt_domain := substring(v_rcpt FROM '@([^@]+)$');
  IF v_rcpt_domain IS NULL OR v_rcpt_domain = '' OR strpos(v_rcpt, '@') <= 1 THEN
    RETURN false;
  END IF;

  SELECT a.tenant_id
    INTO v_tenant_id
    FROM authd.accounts a
   WHERE a.email = v_sender;

  IF v_tenant_id IS NULL THEN
    SELECT g.tenant_id
      INTO v_tenant_id
      FROM authd.groups g
     WHERE g.email = v_sender;
  END IF;

  IF v_tenant_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT ws.auto_forwarding
    INTO v_mode
    FROM identity.workspace_settings ws
   WHERE ws.tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    v_mode := 'workspace'::identity.auto_forwarding_mode;
  END IF;

  IF v_mode = 'off'::identity.auto_forwarding_mode THEN
    RETURN false;
  END IF;

  IF v_mode = 'anywhere'::identity.auto_forwarding_mode THEN
    RETURN true;
  END IF;

  -- `workspace` and `workspace_and_members`: a domain this workspace hosts mail
  -- on and holds now. ⚠ THE SHARED "MAY HOST" PREDICATE, never a copy of it, so
  -- this cannot disagree with what Stalwart delivers and authd signs in to.
  IF EXISTS (
    SELECT 1
      FROM core.mailbox_domain_settings(v_rcpt_domain) m
     WHERE m.tenant_id = v_tenant_id
  ) THEN
    RETURN true;
  END IF;

  -- `workspace_and_members`: also allow an exact match on a current workspace
  -- member's verified sign-in email.
  IF v_mode = 'workspace_and_members'::identity.auto_forwarding_mode THEN
    IF EXISTS (
      SELECT 1
        FROM authd.user_emails ue
        JOIN core.workspace_roles wr
          ON wr.clerk_user_id = ue.clerk_user_id
       WHERE ue.email = v_rcpt
         AND wr.tenant_id = v_tenant_id
    ) THEN
      RETURN true;
    END IF;
  END IF;

  RETURN false;
END;
$$;--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION "core"."auto_forward_allowed"(text, text) FROM PUBLIC;--> statement-breakpoint
-- ⚠ 20260928051303 grants EXECUTE on new core functions to i10_api by default.
-- This definer is exclusively for Stalwart's 'i10' store role.
REVOKE EXECUTE ON FUNCTION "core"."auto_forward_allowed"(text, text) FROM i10_api;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "core"."auto_forward_allowed"(text, text) TO stalwart;--> statement-breakpoint
-- authd gets SELECT on new authd tables by default (20260901120426), but Go
-- authd never reads user sign-in addresses.
REVOKE ALL ON TABLE "authd"."user_emails" FROM authd;
